{"implementation": "def solve(case):
    # Support both wrapped (case_id+payload) and bare payload
    if "payload" in case:
        payload = case["payload"]
    else:
        payload = case

    nodes_list = payload.get("nodes")
    required_symbols_list = payload.get("required_symbols")

    if nodes_list is None:
        raise ValueError("Missing 'nodes' field in payload")
    if required_symbols_list is None:
        raise ValueError("Missing 'required_symbols' field in payload")

    required_symbols = set(required_symbols_list)

    # Validate each node has required fields
    required_node_fields = ["id", "parent", "symbol", "depth", "removable", "utility"]
    for node in nodes_list:
        for field in required_node_fields:
            if field not in node:
                raise ValueError(f"Node missing required field '{field}': {node}")

    # Check for duplicate IDs
    node_ids = [n["id"] for n in nodes_list]
    if len(node_ids) != len(set(node_ids)):
        raise ValueError("Duplicate node IDs detected")

    nodes = {n["id"]: n for n in nodes_list}

    # Validate exactly one root (parent is None)
    root_nodes = [n for n in nodes_list if n["parent"] is None]
    if len(root_nodes) != 1:
        raise ValueError(f"Expected exactly one root node, found {len(root_nodes)}")

    # Build children map and validate all parent references
    children = {nid: [] for nid in nodes}
    for n in nodes_list:
        if n["parent"] is not None:
            if n["parent"] not in nodes:
                raise ValueError(
                    f"Node '{n['id']}' references unknown parent '{n['parent']}'"
                )
            children[n["parent"]].append(n["id"])

    # Validate all required symbols are present in the initial tree
    all_symbols = {n["symbol"] for n in nodes_list}
    missing_symbols = required_symbols - all_symbols
    if missing_symbols:
        raise ValueError(
            f"Required symbols not present in tree: {sorted(missing_symbols)}"
        )

    # retained tracks which nodes are still in the tree
    retained = set(nodes.keys())

    # Candidates: removable nodes only
    # Sort order: depth descending (deeper first), then node ID ascending as stable tiebreak
    candidates = sorted(
        [n for n in nodes_list if n["removable"]],
        key=lambda n: (-n["depth"], n["id"])
    )

    removal_order = []

    for node in candidates:
        nid = node["id"]

        # Skip if already removed in a prior step
        if nid not in retained:
            continue

        # Cannot remove a node that still has retained children
        if any(child in retained for child in children[nid]):
            continue

        # Tentatively remove: check all required symbols still represented
        symbols_after_removal = {
            nodes[r]["symbol"] for r in retained if r != nid
        }
        if required_symbols.issubset(symbols_after_removal):
            retained.discard(nid)
            removal_order.append(nid)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order
    }
"}
